def install_policy():
    import uuid
    codes=['drivers.read','drivers.assign','routes.locations.manage','routes.read','routes.calculate','routes.confirm','routes.recalculate','deliveries.trip.read','deliveries.trip.update','deliveries.trip.own','items.trace.read','items.trace.company']
    conn=op.get_bind()
    for code in codes:
        conn.execute(sa.text('INSERT INTO permissions(id,code,description) VALUES (:id,:code,:description) ON CONFLICT(code) DO NOTHING'),dict(id=uuid.uuid5(uuid.NAMESPACE_URL,'ambs:'+code),code=code,description=code))
    policy={'SUPER_ADMIN':codes,'OPERATIONS':[c for c in codes if c!='deliveries.trip.own'],
        'MANAGEMENT':['drivers.read','routes.read','deliveries.trip.read','items.trace.read','items.trace.company'],
        'SALES':['routes.read','deliveries.trip.read','items.trace.read'],
        'PACKING':['routes.read','deliveries.trip.read','items.trace.read'],
        'ACCOUNTS':['routes.read','deliveries.trip.read'], 'DRIVER':['deliveries.trip.own']}
    for role,grants in policy.items():
        for code in grants:
            conn.execute(sa.text('INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code=:role AND p.code=:code ON CONFLICT DO NOTHING'),dict(role=role,code=code))


def install_guards():
    # Preserve every Phase 6A transition check; add only a narrowly validated driver change.
    conn=op.get_bind()
    original=conn.scalar(sa.text("SELECT pg_get_functiondef('ambs_sales_delivery_guard()'::regprocedure)"))
    insertion='''
      IF TG_OP='UPDATE' AND OLD.driver_id IS DISTINCT FROM NEW.driver_id
        AND (to_jsonb(OLD)-'driver_id')=(to_jsonb(NEW)-'driver_id')
        AND OLD.status NOT IN ('CANCELLED','REVERSED')
        AND NOT EXISTS(SELECT 1 FROM delivery_trip_events WHERE delivery_id=OLD.id)
        AND EXISTS(SELECT 1 FROM delivery_driver_assignments a WHERE a.delivery_id=OLD.id
          AND a.driver_id=NEW.driver_id AND a.previous_driver_id IS NOT DISTINCT FROM OLD.driver_id
          AND a.revision=(SELECT max(revision) FROM delivery_driver_assignments WHERE delivery_id=OLD.id))
        THEN RETURN NEW; END IF;
    '''
    if 'Delivery source is immutable' not in original or 'BEGIN' not in original:
        raise RuntimeError('Unexpected Phase 6A delivery guard; review before upgrade')
    conn.execute(sa.text(original.replace('BEGIN','BEGIN\n'+insertion,1)))
    for table in ['routing_sites','delivery_driver_assignments','delivery_route_calculations','delivery_route_confirmations','delivery_trip_events']:
        op.execute(f'CREATE TRIGGER {table}_history BEFORE UPDATE OR DELETE ON {table} FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_append_only()')
    op.execute('''
    CREATE FUNCTION ambs_assignment_insert_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NOT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=NEW.driver_id AND u.is_active AND r.code='DRIVER')
        OR NOT EXISTS(SELECT 1 FROM sales_deliveries d WHERE d.id=NEW.delivery_id AND d.status NOT IN ('CANCELLED','REVERSED') AND d.driver_id IS NOT DISTINCT FROM NEW.previous_driver_id)
        OR EXISTS(SELECT 1 FROM delivery_trip_events WHERE delivery_id=NEW.delivery_id)
      THEN RAISE EXCEPTION 'Eligible driver and open delivery required' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER assignment_link BEFORE INSERT ON delivery_driver_assignments FOR EACH ROW EXECUTE FUNCTION ambs_assignment_insert_guard();

    CREATE FUNCTION ambs_route_confirm_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NOT EXISTS(SELECT 1 FROM delivery_route_calculations c JOIN sales_deliveries d ON d.id=c.delivery_id
        JOIN delivery_driver_assignments a ON a.delivery_id=d.id
        WHERE c.id=NEW.calculation_id AND c.delivery_id=NEW.delivery_id AND c.status='SUCCESS'
        AND c.revision=(SELECT max(revision) FROM delivery_route_calculations WHERE delivery_id=d.id)
        AND a.id=NEW.assignment_id AND a.driver_id=d.driver_id
        AND a.revision=(SELECT max(revision) FROM delivery_driver_assignments WHERE delivery_id=d.id)
        AND d.status NOT IN ('CANCELLED','REVERSED'))
      THEN RAISE EXCEPTION 'Confirmed route must match current successful route and driver' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER route_confirmation_link BEFORE INSERT ON delivery_route_confirmations FOR EACH ROW EXECUTE FUNCTION ambs_route_confirm_guard();

    CREATE FUNCTION ambs_trip_insert_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NOT EXISTS(SELECT 1 FROM sales_deliveries d JOIN delivery_driver_assignments a ON a.delivery_id=d.id WHERE d.id=NEW.delivery_id AND d.status='DISPATCHED' AND d.driver_id=a.driver_id AND a.id=NEW.assignment_id
        AND a.revision=(SELECT max(revision) FROM delivery_driver_assignments WHERE delivery_id=d.id))
        OR NEW.occurred_at>now()+interval '5 minutes'
        OR (NEW.status='COMPLETED' AND NOT EXISTS(SELECT 1 FROM delivery_trip_events WHERE delivery_id=NEW.delivery_id AND status='ARRIVED' AND occurred_at<=NEW.occurred_at))
      THEN RAISE EXCEPTION 'Trip evidence requires an actual dispatched delivery and valid transition' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER trip_event_link BEFORE INSERT ON delivery_trip_events FOR EACH ROW EXECUTE FUNCTION ambs_trip_insert_guard();
    ''')
